module.exports = /*#__PURE__*/JSON.parse('{"common":{"home":"الرئيسية","books":"الكتب","authors":"المؤلفون","publishers":"الناشرون","whitepaper":"الورقة البيضاء","blog":"المدونة","store":"المتجر","getStarted":"ابدأ الآن","create":"إنشاء","contents":"المحتويات","discoverBookCollection":"اكتشف مجموعتنا من الكتب","exploreBooks":"استكشف مجموعتنا المختارة من الكتب حول البلوك تشين والرموز غير القابلة للاستبدال والويب 3"},"homepage":{"hero":{"heading":"اكتشف الفن الرقمي، اجمع وبيع رموزك غير القابلة للاستبدال المحددة.","text":"تعاون مع أحد أكبر تجار التجزئة في العالم لعرض علامتك التجارية ومنتجاتك."},"faq":{"title":"الأسئلة الشائعة","subtitle":"لديك أسئلة؟ لدينا إجابات","items":[{"title":"ما هو الرمز غير القابل للاستبدال؟","description":"الرمز غير القابل للاستبدال (NFT) هو أصل رقمي فريد يتم التحقق منه باستخدام تقنية البلوك تشين. على عكس العملات المشفرة، كل رمز غير قابل للاستبدال فريد من نوعه ولا يمكن استبداله على أساس واحد لواحد. يمكن أن تمثل الرموز غير القابلة للاستبدال الفن الرقمي والمقتنيات والموسيقى ومقاطع الفيديو والمزيد، مما يوفر دليلاً على الملكية والأصالة."},{"title":"كيف أنشئ وأبيع رمزي غير القابل للاستبدال؟","description":"لإنشاء وبيع رمز غير قابل للاستبدال، قم أولاً بربط محفظة العملات المشفرة الخاصة بك بمنصتنا. انقر على \'إنشاء\' لتحميل ملفك الرقمي (صورة، فيديو، صوت، إلخ)، أضف تفاصيل مثل الاسم والوصف، ثم اختر سلسلة البلوك تشين الخاصة بك وقم بإنشاء رمزك غير القابل للاستبدال. بمجرد الإنشاء، يمكنك إدراجه للبيع بسعر ثابت أو تنسيق مزاد."},{"title":"ما هي المحافظ المدعومة؟","description":"ندعم محافظ العملات المشفرة الرئيسية بما في ذلك MetaMask و WalletConnect و Coinbase Wallet و Trust Wallet. تتيح لك هذه المحافظ تخزين رموزك غير القابلة للاستبدال والعملات المشفرة بشكل آمن والتفاعل مع سوقنا لشراء وبيع وتداول الأصول الرقمية."},{"title":"ما هي رسوم الغاز؟","description":"رسوم الغاز هي تكاليف المعاملات المطلوبة لمعالجة العمليات على شبكة البلوك تشين. تذهب هذه الرسوم إلى مدققي الشبكة وتختلف بناءً على ازدحام الشبكة وتعقيد المعاملة. رسوم الغاز مطلوبة لإنشاء وشراء وبيع الرموز غير القابلة للاستبدال. نوصي بالتحقق من أسعار الغاز الحالية قبل المعاملات."},{"title":"كيف تعمل حقوق الملكية؟","description":"يمكن للمبدعين تعيين نسب مئوية لحقوق الملكية (عادة 5-10٪) عند إنشاء الرموز غير القابلة للاستبدال. هذا يعني أنك ستحصل تلقائياً على نسبة مئوية من المبيعات في كل مرة يتم إعادة بيع رمزك غير القابل للاستبدال في الأسواق الثانوية. حقوق الملكية مدمجة في العقد الذكي ويتم توزيعها تلقائياً على محفظتك."},{"title":"هل رمزي غير القابل للاستبدال آمن؟","description":"نعم، الرموز غير القابلة للاستبدال مؤمنة بتقنية البلوك تشين، مما يجعلها آمنة للغاية ومقاومة للعبث. لكل رمز غير قابل للاستبدال معرف فريد وسجل معاملات مخزن بشكل دائم على البلوك تشين. ومع ذلك، من الضروري الحفاظ على مفاتيحك الخاصة وعبارات البذور الخاصة بمحفظتك بشكل آمن، حيث أن فقدانها يعني فقدان الوصول إلى رموزك غير القابلة للاستبدال."}]}},"authors":{"title":"تعرف على مؤلفينا","subtitle":"اكتشف العقول المبدعة وراء مجموعتنا من الكتب","pageTitle":"مؤلفونا","currentPage":"المؤلفون"},"blog":{"pageTitle":"المدونة","currentPage":"المدونة","sidebarTitle":"المقالات","posts":[{"id":1,"title":"مستقبل أسواق الرموز غير القابلة للاستبدال","excerpt":"استكشف كيف تتطور أسواق الرموز غير القابلة للاستبدال مع التقنيات الجديدة وتجارب المستخدم. من المنصات اللامركزية إلى التوافق بين السلاسل، اكتشف ما ينتظر المقتنيات الرقمية.","author":"سارة جونسون"},{"id":2,"title":"فهم العقود الذكية في الويب 3","excerpt":"دليل شامل للعقود الذكية ودورها في تقنية البلوك تشين وكيفية تشغيلها للتطبيقات اللامركزية. تعلم الأساسيات والمفاهيم المتقدمة.","author":"مايكل تشين"},{"id":3,"title":"أفضل الممارسات للفنانين الرقميين","excerpt":"نصائح واستراتيجيات للفنانين الرقميين الذين يدخلون مجال الرموز غير القابلة للاستبدال. تعلم كيفية إنشاء وتسعير وترويج أعمالك الفنية بشكل فعال في السوق الرقمي.","author":"إيما رودريغيز"},{"id":4,"title":"محافظ العملات المشفرة: دليل شامل","excerpt":"كل ما تحتاج لمعرفته حول محافظ العملات المشفرة، من المحافظ الساخنة إلى التخزين البارد. فهم أفضل ممارسات الأمان واختر المحفظة المناسبة لاحتياجاتك.","author":"ديفيد كيم"},{"id":5,"title":"صعود منصات الميتافيرس","excerpt":"اكتشف كيف تخلق منصات الميتافيرس فرصاً جديدة للمبدعين والشركات والمستخدمين. استكشف العوالم الافتراضية وتأثيرها على الاقتصادات الرقمية.","author":"ليزا أندرسون"},{"id":6,"title":"التمويل اللامركزي موضح: أساسيات التمويل اللامركزي","excerpt":"مقدمة للتمويل اللامركزي (DeFi) وكيفية إحداث ثورة في الأنظمة المالية التقليدية. تعلم عن الإقراض والرهان وزراعة العائد.","author":"جيمس ويلسون"},{"id":7,"title":"بناء استراتيجية مجموعتك من الرموز غير القابلة للاستبدال","excerpt":"نصائح الخبراء حول بناء مجموعة قيمة من الرموز غير القابلة للاستبدال. تعلم عن تحليل السوق وعوامل الندرة واستراتيجيات الاستثمار طويلة الأجل في عالم الفن الرقمي.","author":"صوفيا مارتينيز"},{"id":8,"title":"رسوم الغاز وتحسين المعاملات","excerpt":"أتقن فن إدارة رسوم الغاز على Ethereum والبلوك تشين الأخرى. تعلم متى تقوم بالمعاملات وكيفية تحسين معاملاتك لتقليل التكاليف.","author":"روبرت تايلور"}]},"store":{"pageTitle":"المتجر","breadcrumbTitle":"المتجر","sectionTitle":"منتجاتنا","sectionSubtitle":"اكتشف منتجات عالية الجودة لعشاق الكتب والقراء","buyNow":"اشتري الآن","products":[{"id":1,"name":"قارئ الكتب الإلكترونية المميز","description":"شاشة عالية الدقة مقاس 7 بوصات مع إضاءة قابلة للتعديل. مثالية لقراءة الكتب الرقمية بوضوح وراحة استثنائية.","price":"129.99 دولار","category":"إلكترونيات"},{"id":2,"name":"مجموعة العلامات الكلاسيكية","description":"علامات يدوية الصنع من الجلد بتصاميم أنيقة. مجموعة من 5 علامات مميزة لعشاق الكتب.","price":"24.99 دولار","category":"إكسسوارات"},{"id":3,"name":"مصباح القراءة LED","description":"مصباح قراءة LED قابل لإعادة الشحن مع سطوع قابل للتعديل. تصميم قابل للتثبيت للقراءة بدون استخدام اليدين في أي مكان.","price":"19.99 دولار","category":"إكسسوارات"},{"id":4,"name":"وسادة القراءة","description":"وسادة دعم ظهر مريحة مع مساند للذراعين. دعم مثالي لجلسات القراءة الممتدة في السرير أو على الأريكة.","price":"49.99 دولار","category":"راحة"},{"id":5,"name":"حامل الكتب","description":"حامل كتب قابل للتعديل من الخيزران مع مشابك لحمل الصفحات. يحافظ على الكتب مفتوحة بالزاوية المثالية للقراءة أو الطهي.","price":"34.99 دولار","category":"إكسسوارات"},{"id":6,"name":"مجموعة نظارات القراءة","description":"نظارات قراءة تحجب الضوء الأزرق. علبة من 3 إطارات أنيقة لتقليل إجهاد العين أثناء جلسات القراءة الطويلة.","price":"39.99 دولار","category":"نظارات"},{"id":7,"name":"مساند الكتب العتيقة","description":"مساند كتب معدنية قوية بتصميم كلاسيكي. يحافظ على مجموعتك من الكتب منظمة ويضيف سحراً زخرفياً.","price":"44.99 دولار","category":"تنظيم"},{"id":8,"name":"صندوق اشتراك الكتب","description":"صندوق كتب شهري مختار مع الكتب الأكثر مبيعاً والعناصر الحصرية. انضم إلى آلاف القراء الذين يكتشفون المفضلات الجديدة.","price":"29.99 دولار/شهر","category":"اشتراك"},{"id":9,"name":"سلم المكتبة","description":"سلم مكتبة خشبي متحرك مع أجهزة نحاسية. وصل إلى أعلى أرففك بأناقة وأمان.","price":"299.99 دولار","category":"أثاث"}]},"whitepaper":{"title":"الورقة البيضاء","sections":[{"title":"مقدمة","content":"في العصر الرقمي الحالي، تطور تطوير الواجهة الأمامية إلى ما هو أبعد من HTML و CSS البسيطين. من المتوقع أن توفر واجهات الويب الحديثة أداءً سلساً وإمكانية الوصول واتساق التصميم عبر جميع المنصات. يهدف هذا الويكي إلى توفير رؤى عملية وأدوات وتقنيات تساعد المطورين على إنشاء تطبيقات ويب قابلة للتطوير وقابلة للصيانة وجذابة بصرياً."},{"title":"فهم أداء الويب","content":"يشير أداء الويب إلى مدى سرعة تحميل موقع الويب والاستجابة لتفاعلات المستخدم. تحسين الأداء يحسن رضا المستخدم وترتيب محركات البحث. تشمل الاستراتيجيات الشائعة تقسيم الكود والتحميل البطيء للصور وتقليل حزم JavaScript والاستفادة من شبكات توصيل المحتوى (CDNs)."},{"title":"ما هي سحابة الواجهة الأمامية؟","content":"سحابة الواجهة الأمامية هي بنية تحتية مدارة تسمح للمطورين ببناء ونشر وتوسيع تطبيقات الويب دون إدارة خوادم الواجهة الخلفية. توفر بناءات تلقائية ونشراً مستمراً وتخزين مؤقت وتسليم حافة عالمي. تشمل الأمثلة الشائعة Vercel و Netlify و Cloudflare Pages."},{"title":"أفضل ممارسات التحكم في الإصدار","content":"تسمح أنظمة التحكم في الإصدار مثل Git للفرق بالتعاون بكفاءة. تشمل أفضل الممارسات كتابة رسائل commit واضحة واستخدام فروع الميزات وإجراء مراجعات الكود قبل الدمج ووضع علامات على الإصدارات المستقرة. الحفاظ على تاريخ Git نظيف يساعد في قابلية التطوير للمشروع والتشخيص."},{"title":"مبادئ التصميم المتجاوب","content":"يضمن التصميم المتجاوب أن مواقع الويب تتكيف مع أحجام الشاشات والأجهزة المختلفة. يحقق المطورون ذلك باستخدام شبكات سائلة وصور مرنة واستعلامات CSS الإعلامية. تساعد أدوات مثل Chrome DevTools ومنصات الاختبار عبر الإنترنت في التحقق من الاستجابة عبر نوافذ عرض مختلفة."},{"title":"إمكانية الوصول في تصميم الويب","content":"تضمن إمكانية الوصول أن الأشخاص ذوي الإعاقات يمكنهم استخدام تطبيقات الويب بشكل فعال. يجب على المطورين استخدام HTML الدلالي وتسميات ARIA والحفاظ على تباين لوني كافٍ. الاختبار باستخدام قارئات الشاشة واتباع إرشادات WCAG يحسن قابلية الاستخدام لجميع المستخدمين."},{"title":"مقدمة لتطبيقات الويب التقدمية (PWAs)","content":"تجمع تطبيقات الويب التقدمية بين أفضل ما في تجارب الويب والجوال. تعمل بدون اتصال وترسل إشعارات دفع ويمكن تثبيتها على أجهزة المستخدمين. تستخدم PWAs عمال الخدمة وملفات البيان لتعزيز الموثوقية والمشاركة."},{"title":"إدارة الحالة في React","content":"تتحكم إدارة الحالة في كيفية تدفق البيانات والتحديثات عبر مكونات React. يستخدم المطورون أدوات مثل Context API أو Redux أو Zustand لتحديثات الحالة القابلة للتنبؤ. تحسين الإدارة يحسن الأداء ويمنع سلوك واجهة المستخدم غير المتسق."},{"title":"مقدمة إلى واجهات برمجة التطبيقات","content":"تسمح واجهات برمجة التطبيقات لأنظمة البرمجيات المختلفة بالتواصل. في تطوير الواجهة الأمامية، توفر واجهات برمجة التطبيقات البيانات لعرض المحتوى الديناميكي. REST و GraphQL هما أنماط واجهات برمجة التطبيقات الأكثر شيوعاً، وكلاهما يوفر مزايا فريدة لجلب البيانات والمرونة."},{"title":"الأمان في تطبيقات الواجهة الأمامية","content":"يتضمن أمان الواجهة الأمامية منع هجمات مثل XSS و CSRF و clickjacking. يجب على المطورين تنظيف إدخال المستخدم واستخدام HTTPS وإدارة رموز المصادقة بشكل آمن. توفر أطر مثل Next.js حماية مدمجة للعديد من نقاط الضعف الشائعة."},{"title":"أساسيات الاختبار الآلي","content":"يضمن الاختبار موثوقية التطبيق ويمنع الانحدارات. تتحقق اختبارات الوحدة والتكامل واختبارات نهاية إلى نهاية من طبقات مختلفة من الوظائف. أدوات مثل Jest و Mocha و Cypress شائعة لأتمتة اختبار الواجهة الأمامية."},{"title":"استخدام GitHub للتعاون","content":"يوفر GitHub بيئة تعاونية للمطورين من خلال طلبات السحب والقضايا ولوحات المشاريع. يمكن للفرق أتمتة سير العمل باستخدام GitHub Actions وإجراء مراجعات الكود وتتبع تقدم المشروع في الوقت الفعلي."},{"title":"التكامل المستمر والنشر (CI/CD)","content":"يؤتمت CI/CD عملية اختبار وبناء ونشر التطبيقات. تشمل الأدوات الشائعة GitHub Actions و Jenkins و GitLab CI. تقلل الأتمتة من الأخطاء البشرية وتضمن تسليماً متسقاً لكود عالي الجودة."},{"title":"استراتيجيات التخزين المؤقت لتطبيقات الويب","content":"يحسن التخزين المؤقت الأداء عن طريق تخزين الموارد التي يتم الوصول إليها بشكل متكرر محلياً. تشمل التقنيات تخزين المتصفح المؤقت وتخزين CDN المؤقت وتخزين عمال الخدمة المؤقت للاستخدام بدون اتصال. يضمن إبطال التخزين المؤقت الصحيح أن المستخدمين يتلقون دائماً أحدث إصدار."},{"title":"تحسين الصور للويب","content":"يمكن للصور أن تؤثر بشكل كبير على وقت تحميل الصفحة. يجب على المطورين ضغط الصور واستخدام تنسيقات حديثة مثل WebP أو AVIF وتقديم دقات مناسبة باستخدام عنصر `<picture>` أو سمات متجاوبة مثل `srcset`."},{"title":"الخلاصة","content":"يتطلب تطوير الواجهة الأمامية الحديثة موازنة الأداء والتصميم وإمكانية الوصول. من خلال الاستفادة من منصات السحابة وأدوات الأتمتة ومعايير الويب الناشئة، يمكن للمطورين تقديم تجارب مستخدم استثنائية على نطاق واسع."}]},"books":{"title":"مجموعة الكتب","viewButton":"عرض التفاصيل","by":"الكاتب","items":[{"title":"ثورة البلوك تشين","author":"دون تابسكوت","description":"دليل شامل لفهم تقنية البلوك تشين وإمكاناتها التحويلية عبر الصناعات."},{"title":"إتقان Ethereum","author":"أندرياس م. أنتونوبولوس","description":"بناء العقود الذكية والتطبيقات اللامركزية. نظرة عميقة على بنية وتطوير Ethereum."},{"title":"دليل الرموز غير القابلة للاستبدال","author":"مات فورتناو","description":"كيفية إنشاء وبيع وشراء الرموز غير القابلة للاستبدال. دليلك الكامل لسوق الرموز غير القابلة للاستبدال."},{"title":"معيار البيتكوين","author":"سيف الدين عموص","description":"البديل اللامركزي للبنوك المركزية. فهم دور البيتكوين في مستقبل المال."},{"title":"تداول العملات المشفرة","author":"آلان تي نورمان","description":"تعلم أساسيات واستراتيجيات تداول العملات المشفرة المتقدمة للمبتدئين والمحترفين."},{"title":"مستقبل الويب 3","author":"سارة تشين","description":"استكشاف الإنترنت اللامركزي وتأثيراته على الأعمال والمجتمع والابتكار."}]},"publishers":{"pageTitle":"الناشرون","breadcrumbTitle":"ناشرونا","sectionTitle":"شركاؤنا في النشر","sectionSubtitle":"التعاون مع الناشرين الرائدين لتقديم أفضل المحتوى لك","publishers":[{"id":1,"name":"O\'Reilly Media","description":"ناشر رائد لكتب التكنولوجيا ومنصات التعلم عبر الإنترنت ودورات التدريب المباشرة للمهنيين."},{"id":2,"name":"Manning Publications","description":"ناشر مستقل لكتب الكمبيوتر لمطوري البرمجيات والمهندسين والمهندسين المعماريين والمديرين."},{"id":3,"name":"Wiley","description":"رائد عالمي في نشر البحوث والتعليم، يوفر المعرفة والخدمات للمهنيين في جميع أنحاء العالم."},{"id":4,"name":"Packt Publishing","description":"ناشر كتب التكنولوجيا يركز على مساعدة مطوري البرمجيات ومهنيي تكنولوجيا المعلومات على البقاء في المقدمة."},{"id":5,"name":"Apress","description":"ناشر تقني مكرس لتلبية احتياجات مهنيي تكنولوجيا المعلومات ومطوري البرمجيات والمبرمجين."},{"id":6,"name":"No Starch Press","description":"ناشر مستقل يخلق كتباً مصممة بدقة حول مواضيع التكنولوجيا للهواة وعشاق التكنولوجيا."}]},"footer":{"pagesTitle":"الصفحات","followUsTitle":"تابعنا","copyright":"جميع الحقوق محفوظة.","copyrightText":"خليل السمادي, جميع الحقوق محفوظة","facebook":"فيسبوك","pages":{"home":"الرئيسية","books":"الكتب","authors":"المؤلفون","publishers":"الناشرون","white paper":"الورقة البيضاء","whitepaper":"الورقة البيضاء","blog":"المدونة","store":"المتجر"}}}');

